-- Reserved schema50; concurrent forward-recovery unit owns schema49.
CREATE TABLE claude_code_bindings(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,label TEXT NOT NULL,environment_id TEXT NOT NULL UNIQUE,profile_digest TEXT NOT NULL,root_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','active','disconnected','needs_reauth')),PRIMARY KEY(tenant_id,account_id,id),FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id)) STRICT;
CREATE TABLE claude_code_probes(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,model TEXT NOT NULL,verified_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,account_id,binding_id,revision,model),FOREIGN KEY(tenant_id,account_id,binding_id) REFERENCES claude_code_bindings(tenant_id,account_id,id)) STRICT;
CREATE TABLE personal_claude_selections(tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,binding_id TEXT NOT NULL,revision INTEGER NOT NULL,model TEXT NOT NULL,PRIMARY KEY(tenant_id,account_id),FOREIGN KEY(tenant_id,account_id,binding_id,revision,model) REFERENCES claude_code_probes(tenant_id,account_id,binding_id,revision,model)) STRICT;
CREATE TRIGGER claude_exclusive_insert AFTER INSERT ON personal_claude_selections BEGIN DELETE FROM personal_model_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; DELETE FROM personal_subscription_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER claude_shared_insert AFTER INSERT ON personal_model_selections BEGIN DELETE FROM personal_claude_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER claude_shared_update AFTER UPDATE ON personal_model_selections BEGIN DELETE FROM personal_claude_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER claude_chatgpt_insert AFTER INSERT ON personal_subscription_selections BEGIN DELETE FROM personal_claude_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TRIGGER claude_chatgpt_update AFTER UPDATE ON personal_subscription_selections BEGIN DELETE FROM personal_claude_selections WHERE tenant_id=NEW.tenant_id AND account_id=NEW.account_id; END;
CREATE TABLE claude_code_retirements(environment_id TEXT PRIMARY KEY,profile_digest TEXT NOT NULL,root_id TEXT NOT NULL,account_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('pending','acknowledged'))) STRICT;
CREATE TRIGGER claude_retire_delete AFTER DELETE ON claude_code_bindings BEGIN INSERT OR IGNORE INTO claude_code_retirements VALUES(OLD.environment_id,OLD.profile_digest,OLD.root_id,OLD.account_id,'pending'); END;
CREATE TRIGGER claude_retire_disconnect AFTER UPDATE OF status ON claude_code_bindings WHEN NEW.status IN('disconnected','needs_reauth') BEGIN INSERT OR IGNORE INTO claude_code_retirements VALUES(OLD.environment_id,OLD.profile_digest,OLD.root_id,OLD.account_id,'pending'); END;
CREATE TABLE claude_code_usage(tenant_id TEXT NOT NULL,run_id TEXT NOT NULL,attempt INTEGER NOT NULL,step INTEGER NOT NULL,model TEXT NOT NULL,usage TEXT NOT NULL,PRIMARY KEY(tenant_id,run_id,attempt,step,model)) STRICT;
PRAGMA user_version=50;
